style.content:
/* style.css */

body {
  margin: 0;
  font-family: Arial, sans-serif;
  color: #fff;
  min-height: 100vh;
  /* Gradient background with animation */
  background: linear-gradient(135deg, #99ffff, #651fff);
  background-size: 400% 400%;
  animation: gradientAnimation 15s ease infinite;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 20px;
}

/* Animate the gradient background */
@keyframes gradientAnimation {
  0% {background-position: 0% 50%;}
  50% {background-position: 100% 50%;}
  100% {background-position: 0% 50%;}
}

/* Style header */
header {
  text-align: center;
  margin-bottom: 20px;
}

h1 {
  font-size: 2.5rem;
  margin: 0;
}

button {
  background-color: rgba(255, 255, 255, 0.2);
  border: none;
  padding: 10px 20px;
  font-size: 1rem;
  border-radius: 8px;
  cursor: pointer;
  margin-bottom: 20px;
  color: #00ffff;
  transition: background-color 0.3s ease;
}

button:hover {
  background-color: rgba(255, 255, 255, 0.4);
}

/* Style main sections */
main {
  max-width: 800px;
  width: 100%;
}

section {
  background: rgba(0, 0, 0, 0.3);
  padding: 20px;
  border-radius: 12px;
  margin-bottom: 20px;
}

h2 {
  margin-top: 0;
}

a {
  color: #cc99ff;
  text-decoration: none;
  font-weight: bold;
}

a:hover {
  text-decoration: bold;
}
